import { loadFont as loadMono } from "@remotion/google-fonts/IBMPlexMono";
import { loadFont as loadManrope } from "@remotion/google-fonts/Manrope";
import React, { useEffect, useId, useLayoutEffect } from "react";
import { AbsoluteFill, Easing, interpolate, useCurrentFrame, useVideoConfig } from "remotion";

// Chrome parks a glyph raster on a whole pixel vertically for as long as the
// matrix that carries it is axis-aligned, so text under a slow transform
// clicks along pixel by pixel. A lean too small to see takes it off that grid.
//
// A transform that carries text is marked, and told when it moves:
//
//   const glide = useGlide();
//   transform: `scale(${s})${glide(moving)}`
//
// The mark changes nothing by itself. After every frame the blocks of text
// under a marked transform get the lean: each about its own centre, and each
// by no more than its size on the screen needs. A card, a hairline or an image
// is fine under a transform as it is, so they stay level.
//
// Text leans while its transform moves, and it keeps the lean at rest when it
// rests off the pixel grid (a scene shown smaller in a player, a camera that
// holds at 1.03): dropping the lean there would snap it to the nearest pixel,
// up to half a pixel in one frame, and picking it up would snap it back. Text
// that rests on the grid loses the lean without moving, so a scene at rest at
// full size is drawn exactly as it would be without any of this.

/**
 * Returns `glide(moving)`: append it to a transform that carries text, with
 * `moving` true on the frames where that transform changes.
 *
 * Everything else lives inside this one closure: the build of Studio
 * elements pastes this file whole into the component that uses it, where a
 * second `LEAN` or `lean` at the top level would collide.
 */
const useGlide = (() => {
  /** What `glide(false)` adds to a transform: an identity matrix, to find it by. */
  const AT_REST = " matrix(1, 0, 0, 1, 0, 0)";
  /** `glide(true)` adds it twice. */
  const MOVING = AT_REST + AT_REST;
  const MARKED = `[style*="${AT_REST.trim()}"]`;
  // Text leaves the grid once the matrix leans x into y by half of 1/1024 in
  // device pixels (Skia rounds the glyph matrix to 1/1024). A fifth over it.
  const LEAN = 0.6 / 1024;
  // Past this the text is a speck on the screen; it is left alone.
  const STEEPEST = 5;
  // How far from a whole pixel text may rest and still count as on the grid:
  // the jump it makes when the lean goes is no bigger than this.
  const ON_GRID = 0.05;

  /** The linear part of a 2D matrix: x' = a·x + c·y, y' = b·x + d·y. */
  type Lin = [a: number, b: number, c: number, d: number];
  const LEVEL: Lin = [1, 0, 0, 1];
  const times = (m: Lin, n: Lin): Lin => [
    m[0] * n[0] + m[2] * n[1],
    m[1] * n[0] + m[3] * n[1],
    m[0] * n[2] + m[2] * n[3],
    m[1] * n[2] + m[3] * n[3],
  ];
  const turned = (degrees: number): Lin => {
    const t = (degrees * Math.PI) / 180;
    return [Math.cos(t), Math.sin(t), -Math.sin(t), Math.cos(t)];
  };
  const offWhole = (n: number) => Math.abs(n - Math.round(n));

  type Block = HTMLElement | SVGTextElement | SVGSVGElement;
  let leant: Block[] = [];
  // Fonts arrive after the first pass and change what is laid out where, with
  // no render to follow: a block or a marked element that changes size is read
  // again before the frame is painted.
  let watcher: ResizeObserver | undefined;
  const watched = new WeakSet<Element>();
  const watch = (el: Element) => {
    if (watched.has(el)) return;
    watched.add(el);
    watcher ??= new ResizeObserver(() => lean());
    watcher.observe(el);
  };

  const depthOf = (el: Element) => {
    let depth = 0;
    for (let up = el.parentElement; up; up = up.parentElement) depth += 1;
    return depth;
  };

  /** The nearest box around a text node that a transform applies to. */
  const blockOf = (node: Node): Block | null => {
    for (let el = node.parentElement; el; el = el.parentElement) {
      if (el instanceof SVGElement) {
        const text = el.closest("text");
        if (!(text instanceof SVGTextElement)) return null;
        // Text that only shapes a mask or a clip is not drawn where it stands
        // and cannot turn by itself: its whole drawing leans for it.
        if (!text.closest("defs, mask, clipPath, pattern, symbol, marker"))
          return text;
        let drawing = text.ownerSVGElement;
        while (drawing?.ownerSVGElement) drawing = drawing.ownerSVGElement;
        return drawing;
      }
      if (!(el instanceof HTMLElement)) continue;
      const { display } = getComputedStyle(el);
      if (display !== "inline" && display !== "contents") return el;
    }
    return null;
  };

  /** One pass over the page: what every element's own transforms do. */
  function reader(given: Map<Element, number>) {
    type Own = {
      /** `scale` and `transform`, without the `rotate` property. */
      lin: Lin;
      /** `rotate`, in degrees: a lean given in this pass, or the scene's own. */
      turn: number;
      /** How far down it is moved, and by what whole factor it is scaled from
       * its top left corner; null when it does anything else. */
      carry: { dy: number; k: number } | null;
    };
    const lens = new Map<Element, boolean>();
    /** Whether an element shows its children in perspective. */
    const lensOn = (el: Element | null): boolean => {
      if (!el) return false;
      const seen = lens.get(el);
      if (seen !== undefined) return seen;
      const style = getComputedStyle(el);
      const result =
        style.perspective !== "none" ||
        (style.transformStyle === "preserve-3d" && lensOn(el.parentElement));
      lens.set(el, result);
      return result;
    };
    const own = new Map<Element, Own | null>();
    const ownOf = (el: Element): Own | null => {
      const seen = own.get(el);
      if (seen !== undefined) return seen;
      const style = getComputedStyle(el);
      const m = new DOMMatrixReadOnly(
        style.transform === "none" ? "" : style.transform,
      );
      const scale = style.scale === "none" ? [] : style.scale.split(" ");
      const sx = scale.length ? Number.parseFloat(scale[0]) : 1;
      const sy = scale.length > 1 ? Number.parseFloat(scale[1]) : sx;
      const rotate = style.rotate === "none" ? [] : style.rotate.split(" ");
      let result: Own | null = null;
      // Seen in perspective, text is drawn on a layer of its own: not ours. A
      // turn out of the plane without perspective lands flat on the screen,
      // and text under it snaps like any other.
      // A push along z alone, or a half turn, leaves it flat even under a lens.
      const inPerspective =
        Math.max(Math.abs(m.m14), Math.abs(m.m24), Math.abs(m.m34)) > 1e-9 ||
        (Math.max(
          Math.abs(m.m13),
          Math.abs(m.m31),
          Math.abs(m.m23),
          Math.abs(m.m32),
        ) > 1e-6 &&
          lensOn(el.parentElement));
      if (!inPerspective && rotate.length < 2) {
        // The `scale` property acts on what `transform` has produced.
        const lin: Lin = [m.a * sx, m.b * sy, m.c * sx, m.d * sy];
        const moved =
          style.translate === "none"
            ? 0
            : (style.translate.split(" ")[1] ?? "0px");
        const k = Math.round(lin[0]);
        const whole =
          m.is2D &&
          k >= 1 &&
          Math.abs(lin[0] - k) < 1e-4 &&
          Math.abs(lin[3] - k) < 1e-4 &&
          Math.abs(lin[1]) < 1e-5 &&
          Math.abs(lin[2]) < 1e-5 &&
          rotate.length === 0 &&
          (moved === 0 || moved.endsWith("px")) &&
          // Scaled about its corner, a box stays where layout put it.
          (k === 1 || /^0(px)? 0(px)?/.test(style.transformOrigin));
        result = {
          lin,
          turn: rotate.length ? Number.parseFloat(rotate[0]) : 0,
          carry: whole
            ? { dy: sy * m.f + (moved === 0 ? 0 : Number.parseFloat(moved)), k }
            : null,
        };
      }
      own.set(el, result);
      return result;
    };
    const down = new Map<Element, Lin | null>();
    /** Everything from the page down to and including this element. */
    const linDown = (el: Element | null): Lin | null => {
      if (!el) return LEVEL;
      const seen = down.get(el);
      if (seen !== undefined) return seen;
      const above = linDown(el.parentElement);
      const mine = above && ownOf(el);
      const result =
        above && mine
          ? times(times(above, turned(given.get(el) ?? mine.turn)), mine.lin)
          : null;
      down.set(el, result);
      return result;
    };
    const carried = new Map<Element, { dy: number; k: number } | null>();
    const carryDown = (
      el: Element | null,
    ): { dy: number; k: number } | null => {
      if (!el) return { dy: 0, k: 1 };
      const seen = carried.get(el);
      if (seen !== undefined) return seen;
      const above = carryDown(el.parentElement);
      const mine = above && !given.has(el) ? ownOf(el)?.carry : null;
      const result =
        above && mine
          ? { dy: above.dy + above.k * mine.dy, k: above.k * mine.k }
          : null;
      carried.set(el, result);
      return result;
    };
    return { ownOf, linDown, carryDown };
  }

  /**
   * Whether text in an SVG rests on the grid: it is placed wherever it is told
   * to, so only when it is shown one to one and its baseline happens to land on
   * a whole pixel. `lands` is where its own space lands on the screen.
   */
  function restsOnGrid(text: SVGTextElement, lands: DOMMatrix | null) {
    if (!lands) return false;
    const dpr = window.devicePixelRatio;
    const style = getComputedStyle(text);
    const k = lands.d * dpr;
    const y = text.y.baseVal.numberOfItems
      ? text.y.baseVal.getItem(0).value
      : 0;
    return (
      text.y.baseVal.numberOfItems <= 1 &&
      text.dy.baseVal.numberOfItems === 0 &&
      !text.querySelector("tspan[y], tspan[dy], textPath") &&
      /^(auto|alphabetic)$/.test(style.dominantBaseline) &&
      /^(auto|baseline)$/.test(style.alignmentBaseline) &&
      Math.abs(lands.b) < 1e-6 &&
      Math.abs(lands.c) < 1e-6 &&
      Math.round(k) >= 1 &&
      offWhole(k) < 2e-3 &&
      offWhole((lands.d * y + lands.f) * dpr) < ON_GRID
    );
  }

  /**
   * The angle that takes a block off the grid, given what is above it (`above`)
   * and what its own transform does (`own`), both in device pixels: the lean is
   * a turn between the two. 0 when the block leans enough as it is, null when
   * no sane angle would do.
   */
  function angleFor(above: Lin, own: Lin): number | null {
    // y from x of `above · turn(θ) · own` is p·sin θ + q·cos θ.
    const p = above[3] * own[0] - above[1] * own[1];
    const q = above[1] * own[0] + above[3] * own[1];
    if (Math.abs(q) >= LEAN) return 0;
    if (Math.abs(p) < 1e-9) return null;
    // Along the turn the scene already has, so the two never cancel out.
    const sine = ((q < 0 ? -LEAN : LEAN) - q) / p;
    if (Math.abs(sine) > Math.sin((STEEPEST * Math.PI) / 180)) return null;
    return (Math.asin(sine) * 180) / Math.PI;
  }

  function lean() {
    for (const el of leant) {
      el.style.removeProperty("rotate");
      if (el instanceof SVGElement) el.style.removeProperty("translate");
    }
    leant = [];
    const zones = document.querySelectorAll<HTMLElement | SVGElement>(MARKED);
    if (zones.length === 0) return;
    // Each block of text under a mark, and whether any transform above it moves.
    const blocks = new Map<Block, boolean>();
    // The texts a whole drawing leans for.
    const standsFor = new Map<SVGSVGElement, SVGTextElement[]>();
    for (const zone of zones) {
      const moving = zone.style.transform.includes(MOVING.trim());
      const walker = document.createTreeWalker(zone, NodeFilter.SHOW_TEXT);
      for (let node = walker.nextNode(); node; node = walker.nextNode()) {
        if (!/\S/.test(node.nodeValue ?? "")) continue;
        const block = blockOf(node);
        // A block that turns by a property of its own is left to the scene.
        if (!block || block.style.rotate) continue;
        blocks.set(block, moving || (blocks.get(block) ?? false));
        const text = node.parentElement?.closest("text");
        if (block instanceof SVGSVGElement && text instanceof SVGTextElement)
          standsFor.set(block, [...(standsFor.get(block) ?? []), text]);
      }
      watch(zone);
    }
    for (const block of blocks.keys()) watch(block);
    const dpr = window.devicePixelRatio;
    const scaled = (m: Lin): Lin => [
      m[0] * dpr,
      m[1] * dpr,
      m[2] * dpr,
      m[3] * dpr,
    ];
    // Outer blocks first: a block inside a leaning one takes only what it
    // still lacks, so leans never pile up. Everything is read before anything
    // is written; `given` stands in for the leans not yet on the page.
    const given = new Map<Element, number>();
    const { ownOf, linDown, carryDown } = reader(given);
    const writes: (() => void)[] = [];
    const ordered = [...blocks.keys()].sort((a, b) => depthOf(a) - depthOf(b));
    for (const el of ordered) {
      const moving = blocks.get(el) === true;
      if (el instanceof HTMLElement) {
        const above = linDown(el.parentElement);
        const mine = ownOf(el);
        if (!above || !mine) continue;
        if (!moving) {
          // Layout puts a baseline on a whole pixel wherever the box itself
          // sits, so text is on the grid when the transforms around it only
          // move it by whole pixels and show it one to one (or two, or three).
          const carry = carryDown(el);
          if (
            carry &&
            offWhole(carry.k * dpr) < 2e-3 &&
            offWhole(carry.dy * dpr) < ON_GRID
          )
            continue;
        }
        const angle = angleFor(scaled(above), mine.lin);
        if (!angle) continue;
        given.set(el, angle);
        writes.push(() => el.style.setProperty("rotate", `${angle}deg`));
        leant.push(el);
        continue;
      }
      if (el instanceof SVGSVGElement) {
        // A whole drawing: what it does itself is its own transform and the
        // scale of its viewBox, read off where it lands on the screen.
        const above = linDown(el.parentElement);
        const lands = el.getScreenCTM();
        const det = above ? above[0] * above[3] - above[1] * above[2] : 0;
        if (!above || !lands || Math.abs(det) < 1e-12) continue;
        if (
          !moving &&
          (standsFor.get(el) ?? []).every((text) =>
            restsOnGrid(text, text.getScreenCTM()),
          )
        )
          continue;
        const mine = times(
          [above[3] / det, -above[1] / det, -above[2] / det, above[0] / det],
          [lands.a, lands.b, lands.c, lands.d],
        );
        const angle = angleFor(scaled(above), mine);
        if (!angle) continue;
        given.set(el, angle);
        writes.push(() => el.style.setProperty("rotate", `${angle}deg`));
        leant.push(el);
        continue;
      }
      // Its drawing leans as a whole already.
      let drawing = el.ownerSVGElement;
      while (drawing?.ownerSVGElement) drawing = drawing.ownerSVGElement;
      if (drawing && given.has(drawing)) continue;
      // Text in an SVG is placed wherever it is told to, so it is on the grid
      // only when its baseline happens to land on a whole pixel.
      const frame = el.parentNode;
      if (!(frame instanceof SVGGraphicsElement) || el.style.translate)
        continue;
      const outer = frame.getScreenCTM();
      const whole = el.getScreenCTM();
      if (
        !outer ||
        !whole ||
        Math.abs(outer.a * outer.d - outer.b * outer.c) < 1e-12
      )
        continue;
      // What the text element itself does, in the space it is placed in.
      const mine = outer.inverse().multiply(whole);
      if (!moving && restsOnGrid(el, whole)) continue;
      const angle = angleFor(scaled([outer.a, outer.b, outer.c, outer.d]), [
        mine.a,
        mine.b,
        mine.c,
        mine.d,
      ]);
      if (!angle) continue;
      // An SVG element turns about the corner of its drawing. A move brings
      // the turn to the middle of the text instead.
      const box = el.getBBox();
      const [cx, cy] = [box.x + box.width / 2, box.y + box.height / 2];
      const [px, py] = [
        mine.a * cx + mine.c * cy + mine.e,
        mine.b * cx + mine.d * cy + mine.f,
      ];
      const [cos, sin] = [turned(angle)[0], turned(angle)[1]];
      const [tx, ty] = [px - (px * cos - py * sin), py - (px * sin + py * cos)];
      writes.push(() => {
        el.style.setProperty("rotate", `${angle}deg`);
        el.style.setProperty("translate", `${tx}px ${ty}px`);
      });
      leant.push(el);
    }
    for (const write of writes) write();
  }

  const useFrameEffect =
    typeof window === "undefined" ? useEffect : useLayoutEffect;

  function useGlide() {
    // No dependencies: the lean follows whatever this frame laid out.
    useFrameEffect(lean);
    return glide;
  }

  const glide = (moving: boolean) => (moving ? MOVING : AT_REST);

  return useGlide;
})();

const { fontFamily: mono } = loadMono("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});
const manrope = loadManrope("normal", {
  weights: ["500", "600"],
  subsets: ["latin"],
});

export interface LogoConstructProps {
  /** Replaces the constructed R. The construction still draws, then your logo settles in its place. */
  logo?: React.ReactNode;
  /** Letters set after the R, on its baseline, in Manrope 600. The real logo reads R + "emocn". */
  name?: string;
  accent?: string;
  /** Color of the name and the R's outline; overrides the theme ink. */
  ink?: string;
  /** Paper fill; "transparent" drops it with the vignette and grain. */
  background?: string;
  /** Typeface for the name. Load it yourself; Manrope by default. */
  fontFamily?: string;
  /** Frames between letters of the name as they rise. */
  stagger?: number;
  /** The paper grid behind the construction. */
  grid?: boolean;
  /** Size of the drawing around the frame's center; hairlines stay 1px. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  /** Film grain over the scene. */
  grain?: boolean;
  /** Playback multiplier. */
  speed?: number;
  /** Light = blueprint paper (default); dark = drafting film on black. */
  theme?: "light" | "dark";
}

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_DRAW = Easing.bezier(0.45, 0, 0.2, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

// gradients.sh "mesh" palette: bg #0a0d24, [#ecdcf2, #8796ee, #2e45b7, #0e1645].
// It fills the constructed R: a mesh of soft blobs inside the letter.
const THEMES = {
  light: {
    bg: "#F5F4F0",
    ink: "#121214",
    guideMix: 0,
    gridAlpha: 0.075,
    majorAlpha: 0.13,
    guideAlpha: 0.62,
    label: 0.9,
    vignette: "rgba(120,110,90,0.10)",
    grain: 0.05,
    meshBase: "#0a0d24",
    // [colour, x, y, radius, opacity] per blob, in the R's bounding box
    mesh: [
      ["#ecdcf2", 0.58, 0.1, 0.42, 0.55],
      ["#8796ee", 0.95, 0.32, 0.7, 1],
      ["#2e45b7", 0.74, 0.92, 0.7, 1],
      ["#0e1645", 0.12, 0.72, 0.7, 1],
    ],
  },
  dark: {
    bg: "#0A0A0B",
    ink: "#F3F2EF",
    guideMix: 0.45,
    gridAlpha: 0.07,
    majorAlpha: 0.12,
    guideAlpha: 0.7,
    label: 0.95,
    vignette: "rgba(0,0,0,0.55)",
    grain: 0.06,
    meshBase: "#2e45b7",
    mesh: [
      ["#ecdcf2", 0.6, 0.12, 0.5, 0.9],
      ["#8796ee", 0.12, 0.22, 0.7, 1],
      ["#2e45b7", 0.74, 0.9, 0.7, 1],
      ["#8796ee", 0.2, 0.86, 0.5, 0.8],
    ],
  },
} as const;

const REMOCN_R_PATH =
  "M 0.01 0.81 C 0.01 1.73, 0.36 2.79, 1.09 4.13 C 4.91 11.04, 13.45 17.16, 21.7 18.9 C 22.94 19.16, 23.18 19.16, 51.39 19.27 C 76.07 19.36, 80.02 19.4, 81.32 19.57 C 89.89 20.69, 96.2 24.68, 99.38 31.01 C 103.19 38.56, 102.53 50.1, 97.91 57.07 C 94.66 61.96, 89.68 64.99, 83.26 66 C 82.81 66.07, 70.18 66.83, 55.2 67.69 C 24.82 69.43, 27.03 69.23, 24.18 70.4 C 19.9 72.15, 14.84 75.7, 10.65 79.89 C 4.86 85.68, 1.3 91.91, 0.25 98.13 C 0.12 98.85, 0.08 103.13, 0.04 116.66 L 0 134.26 9.5 134.26 L 19 134.26 19.05 119.41 C 19.1 103.27, 19.08 103.82, 19.82 101.04 C 21.79 93.65, 27.86 88.75, 36.45 87.63 C 37.23 87.53, 39.41 87.5, 43.57 87.53 C 50.12 87.59, 50.75 87.65, 53.22 88.45 C 56.61 89.56, 59.67 91.86, 62.02 95.07 C 62.52 95.76, 69.35 103.85, 77.2 113.07 C 85.04 122.28, 91.63 130.04, 91.85 130.32 C 92.07 130.59, 92.5 131.34, 92.82 131.97 C 93.52 133.35, 94.11 133.93, 95.06 134.13 C 95.5 134.23, 98.97 134.26, 106.36 134.23 L 117.01 134.19 100.82 113.07 C 91.91 101.45, 84.52 91.78, 84.39 91.57 C 83.36 89.89, 83.66 87.53, 85.09 86 C 85.79 85.25, 86.36 84.94, 88.07 84.38 C 96.18 81.72, 104.15 76.62, 109.97 70.36 C 120.59 58.93, 124.06 44.32, 119.44 30.43 C 114.59 15.81, 101.93 4.02, 87.64 0.83 C 83.93 0.01, 88.09 0.08, 41.85 0.04 L 0.01 0 0.01 0.81 Z";

// Construction geometry, measured off the R path (R units, y down, 134.26 tall).
const R_W = 121.44;
const H = 134.26;
/** One stroke module: the bar, stem, mid bar and bowl are all ~1/7 of the height. */
const M = H / 7;
/** Bowl: concentric arcs around one centre. */
const BOWL = { x: 79.6, y: 42.6, ro: 41.9, ri: 23.1 };
const BAR_IN = 19.3;
const MID_TOP = 67.7;
const MID_BOT = 87.6;
const STEM_R = 19;
/** Leg: the outer edge runs from (84.4, 91.6) to the foot at (117, 134.2). */
const LEG = { x0: 84.4, y0: 91.6, x1: 117, y1: 134.2 };
const LEG_DEG = (Math.atan2(LEG.y1 - LEG.y0, LEG.x1 - LEG.x0) * 180) / Math.PI;
/** Bezier anchors + handles of the two transitions that give the R its voice. */
const HANDLES = [
  // the top-left swash
  { a: [21.7, 18.9], h: [13.45, 17.16] },
  { a: [1.09, 4.13], h: [4.91, 11.04] },
  // the mid bar turning down into the stem
  { a: [10.65, 79.89], h: [14.84, 75.7] },
  { a: [10.65, 79.89], h: [4.86, 85.68] },
  { a: [19.82, 101.04], h: [21.79, 93.65] },
  { a: [36.45, 87.63], h: [27.86, 88.75] },
] as const;

// The wordmark, set like the site header: R is 0.76em tall, "emocn" Manrope 600 at -0.025em.
const FONT = H / 0.76;
const X_HEIGHT = 0.54;
const WORD_XLINE = H - FONT * X_HEIGHT;
const TRACK = -0.025;
/** Manrope 600 advances, per em. */
const ADV: Record<string, number> = {
  a: 0.57,
  c: 0.568,
  e: 0.596,
  i: 0.264,
  l: 0.264,
  m: 0.882,
  n: 0.615,
  o: 0.61,
  r: 0.386,
  s: 0.536,
  t: 0.422,
  " ": 0.26,
};
const WORD_X = 124.06 + FONT * 0.04;
const RISE = FONT * 0.8;

function hexRgb(hex: string) {
  const h = hex.replace("#", "");
  const n = Number.parseInt(
    h.length === 3
      ? h
          .split("")
          .map((c) => c + c)
          .join("")
      : h,
    16,
  );
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

function tint(hex: string, mixWhite: number, alpha: number) {
  const [r, g, b] = hexRgb(hex).map((c) =>
    Math.round(c + (255 - c) * mixWhite),
  );
  return `rgba(${r},${g},${b},${alpha})`;
}

/** Polyline of a circular arc, angles in degrees, y down (270 = up). */
function arc(cx: number, cy: number, r: number, a0: number, sweep: number) {
  const steps = Math.max(2, Math.ceil(Math.abs(sweep) / 3));
  let d = "";
  for (let i = 0; i <= steps; i++) {
    const a = ((a0 + (sweep * i) / steps) * Math.PI) / 180;
    d += `${i ? "L" : "M"}${cx + Math.cos(a) * r} ${cy + Math.sin(a) * r}`;
  }
  return d;
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.85"
          numOctaves={2}
          seed={11}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

export function LogoConstruct({
  logo,
  name = "emocn",
  accent = "#3B5BFD",
  ink,
  background,
  fontFamily = manrope.fontFamily,
  stagger = 3,
  grid = true,
  scale = 1,
  delay = 0,
  grain = true,
  speed = 1,
  theme = "light",
}: LogoConstructProps) {
  const glide = useGlide();
  const t = Math.max(0, useCurrentFrame() - delay) * speed;
  const { width, height } = useVideoConfig();
  const u = height / 720;
  const pal = THEMES[theme];
  const fg = ink ?? pal.ink;
  const transparent = background === "transparent";
  const stage = transparent ? "transparent" : (background ?? pal.bg);
  const knock = transparent ? pal.bg : stage;
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");

  const p = (a: number, b: number, easing = EASE_DRAW) =>
    interpolate(t, [a, b], [0, 1], { ...CLAMP, easing });

  // ---- camera: tight on the R, then an eased pull back to the lockup ----
  const wordW =
    name.split("").reduce((w, ch) => w + (ADV[ch] ?? 0.6) + TRACK, 0) * FONT;
  const lockL = 0;
  const lockR = WORD_X + wordW;
  const dimRoom = 30;
  const s1 = 3.05 * u;
  const s2 = Math.min((width * 0.6) / (lockR + dimRoom - lockL), 1.25 * u);
  const pull = p(120, 168, EASE_IO);
  const drift = interpolate(t, [0, 120], [0, 1], CLAMP);
  const sCam = Math.exp(
    interpolate(
      pull,
      [0, 1],
      [Math.log(s1 * (0.965 + drift * 0.035)), Math.log(s2)],
    ),
  );
  const camX = interpolate(pull, [0, 1], [R_W / 2 + 4, (lockL + lockR) / 2]);
  const camY = interpolate(pull, [0, 1], [H / 2 - 2, H / 2 + 4]);
  const hold = interpolate(t, [160, 260], [1, 1.03], {
    ...CLAMP,
    easing: EASE_IO,
  });
  // scale goes through the camera so the grid still fills the frame and
  // hairlines stay 1px
  const s = sCam * hold * scale;
  const tx = width / 2 - camX * s;
  const ty = height / 2 - camY * s;
  const px = (n: number) => n / s; // screen px -> units at the current zoom
  // Chrome parks a glyph raster on a whole pixel vertically for as long as the
  // matrix is axis-aligned, so the labels and the name under the slow camera
  // click along pixel by pixel. SVG text can't carry the mark, so the drawing
  // carries it, moving while the camera moves.
  // The pull starts as the drift ends and both ease in or out there, so the
  // motion is read off the neighbouring frames rather than off progress.
  const drivers = (f: number) => [
    interpolate(f, [0, 120], [0, 1], CLAMP),
    interpolate(f, [120, 168], [0, 1], { ...CLAMP, easing: EASE_IO }),
    interpolate(f, [160, 260], [0, 1], { ...CLAMP, easing: EASE_IO }),
  ];
  const now = drivers(t);
  const camMoving = [drivers(t - speed), drivers(t + speed)].some((d) =>
    d.some((v, i) => v !== now[i]),
  );

  // visible range in units, for grid + infinite guides
  const vx0 = (0 - tx) / s;
  const vx1 = (width - tx) / s;
  const vy0 = (0 - ty) / s;
  const vy1 = (height - ty) / s;

  // ---- colours ----
  const guide = tint(accent, pal.guideMix, 1);
  const guideA = (a: number) => tint(accent, pal.guideMix, a);

  // guides settle to hairlines once the mark is solid
  const settle = p(112, 150, EASE_IO);
  const guideLevel = interpolate(settle, [0, 1], [pal.guideAlpha, 0.2]);
  const labelLevel = interpolate(p(110, 132, EASE_IO), [0, 1], [pal.label, 0]);

  // ---- paper grid on the module (half-module minor, module major) ----
  const gridIn = 0.45 + 0.55 * p(0, 18, EASE_OUT);
  const minorStep = M / 2;
  const minorAlpha =
    pal.gridAlpha *
    gridIn *
    interpolate(minorStep * s, [10 * u, 26 * u], [0.25, 1], CLAMP);
  const gridLines: React.ReactNode[] = [];
  for (let i = Math.floor(vx0 / minorStep); i * minorStep <= vx1; i++) {
    const gx = i * minorStep;
    const major = i % 2 === 0;
    gridLines.push(
      <line
        key={`gx${i}`}
        x1={gx}
        x2={gx}
        y1={vy0}
        y2={vy1}
        stroke={guideA(major ? pal.majorAlpha * gridIn : minorAlpha)}
        strokeWidth={px(1)}
      />,
    );
  }
  for (let i = Math.floor(vy0 / minorStep); i * minorStep <= vy1; i++) {
    const gy = i * minorStep;
    const major = i % 2 === 0;
    gridLines.push(
      <line
        key={`gy${i}`}
        y1={gy}
        y2={gy}
        x1={vx0}
        x2={vx1}
        stroke={guideA(major ? pal.majorAlpha * gridIn : minorAlpha)}
        strokeWidth={px(1)}
      />,
    );
  }

  // ---- infinite guides that grow out from the R ----
  const span = Math.max(vx1 - vx0, vy1 - vy0) * 1.2;
  const hGuides = [
    { y: 0, from: 60, at: 8 },
    { y: H, from: 60, at: 11 },
    { y: BOWL.y, from: BOWL.x, at: 16 },
    { y: BAR_IN, from: 50, at: 19 },
    { y: MID_TOP, from: 50, at: 22 },
    { y: MID_BOT, from: 50, at: 25 },
  ];
  const vGuides = [
    { x: 0, from: 67, at: 13 },
    { x: STEM_R, from: 67, at: 17 },
    { x: BOWL.x, from: BOWL.y, at: 21 },
    { x: R_W, from: BOWL.y, at: 24 },
  ];
  // the wordmark re-lights the baseline
  const relight = p(146, 166, EASE_OUT) * (1 - p(196, 230, EASE_IO) * 0.5);
  const lineAlpha = (y?: number) =>
    y === H ? guideLevel + relight * (pal.guideAlpha - 0.2) * 0.9 : guideLevel;

  // ---- construction draw windows ----
  const crossIn = p(28, 40, EASE_OUT);
  const radius = p(32, 46);
  const outer = p(36, 66);
  const inner = p(48, 64);
  const dims = p(44, 60, EASE_OUT);
  const ruler = p(40, 64);
  const leg = p(54, 72);
  const legArc = p(60, 76);
  const handles = HANDLES.map((_, i) => p(58 + i * 3, 70 + i * 3, EASE_OUT));
  const outline = p(72, 106);
  const fill = p(96, 128, EASE_IO);
  const markDone = p(122, 134, EASE_OUT);

  const hair = px(1 * u);
  const thin = px(1.25 * u);
  const dash = `${px(3 * u)} ${px(3.5 * u)}`;
  const fs = px(12 * u);

  const Label = ({
    x,
    y,
    children,
    anchor = "start",
    o = 1,
    rotate,
  }: {
    x: number;
    y: number;
    children: React.ReactNode;
    anchor?: "start" | "middle" | "end";
    o?: number;
    rotate?: number;
  }) => (
    <text
      x={x}
      y={y}
      textAnchor={anchor}
      fontFamily={mono}
      fontSize={fs}
      fontWeight={500}
      letterSpacing={px(0.2 * u)}
      fill={guide}
      opacity={o * labelLevel}
      transform={rotate ? `rotate(${rotate} ${x} ${y})` : undefined}
      style={{ fontVariantNumeric: "tabular-nums" }}
    >
      {children}
    </text>
  );

  const tick = (x: number, y: number, vertical: boolean, len = 3) =>
    vertical ? (
      <line x1={x} x2={x} y1={y - len} y2={y + len} />
    ) : (
      <line x1={x - len} x2={x + len} y1={y} y2={y} />
    );

  // the fill sweeps round the bowl centre, like the compass did
  const wedge = (() => {
    const sweep = 360 * fill;
    if (sweep <= 0) return "M0 0z";
    if (sweep >= 359.9) return `M-400 -400H600V600H-400z`;
    return `M${BOWL.x} ${BOWL.y}${arc(BOWL.x, BOWL.y, 400, 180, sweep).replace("M", "L")}Z`;
  })();

  // mesh blobs drift a few percent over the shot
  const blob = (bx: number, by: number, k: number) => ({
    cx: R_W * (bx + Math.sin(t / 47 + k * 1.7) * 0.04),
    cy: H * (by + Math.cos(t / 53 + k * 2.3) * 0.03),
  });
  const blobs = pal.mesh.map(([c, bx, by, r, o], k) => ({
    ...blob(bx, by, k),
    c,
    r: R_W * r,
    o,
  }));

  // wordmark letters rise out of the baseline, 3 frames apart
  const letters = name.split("");
  const letterP = (i: number) =>
    p(144 + i * stagger, 164 + i * stagger, EASE_OUT);
  const wordGuides = p(140, 160, EASE_OUT);
  const xGrow = p(138, 166);
  const wordSettle = p(198, 232, EASE_IO);
  const dimX = lockR + 14;

  // logo overlay geometry (screen)
  const markScreen = {
    left: tx,
    top: ty,
    size: H * s,
  };
  const logoIn = p(100, 126, EASE_OUT);

  const legLen = Math.hypot(LEG.x1 - LEG.x0, LEG.y1 - LEG.y0);
  const legUx = (LEG.x1 - LEG.x0) / legLen;
  const legUy = (LEG.y1 - LEG.y0) / legLen;

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <svg
        width={width}
        height={height}
        style={{ position: "absolute", inset: 0, transform: glide(camMoving) }}
        aria-hidden
      >
        <defs>
          <clipPath id={`fill${uid}`} clipPathUnits="userSpaceOnUse">
            <path d={wedge} />
          </clipPath>
          {blobs.map((b, i) => (
            <radialGradient
              key={i}
              id={`mesh${uid}${i}`}
              gradientUnits="userSpaceOnUse"
              cx={b.cx}
              cy={b.cy}
              r={b.r}
            >
              <stop offset="0%" stopColor={b.c} stopOpacity={b.o} />
              <stop offset="68%" stopColor={b.c} stopOpacity={0} />
            </radialGradient>
          ))}
          <clipPath id={`word${uid}`} clipPathUnits="userSpaceOnUse">
            <rect
              x={WORD_X - 10}
              y={-200}
              width={wordW + 60}
              height={H + 200.5}
            />
          </clipPath>
        </defs>
        <g transform={`translate(${tx} ${ty}) scale(${s})`}>
          {grid ? gridLines : null}

          {/* infinite construction guides */}
          <g stroke={guide} strokeWidth={hair} fill="none">
            {hGuides.map((g) => {
              const k = p(g.at, g.at + 26);
              return (
                <line
                  key={`h${g.y}`}
                  x1={g.from - span * k}
                  x2={g.from + span * k}
                  y1={g.y}
                  y2={g.y}
                  opacity={lineAlpha(g.y)}
                />
              );
            })}
            {vGuides.map((g) => {
              const k = p(g.at, g.at + 26);
              return (
                <line
                  key={`v${g.x}`}
                  y1={g.from - span * k}
                  y2={g.from + span * k}
                  x1={g.x}
                  x2={g.x}
                  opacity={guideLevel}
                />
              );
            })}
          </g>

          {/* compass, ruler and handle work */}
          <g
            stroke={guide}
            fill="none"
            strokeWidth={thin}
            opacity={interpolate(settle, [0, 1], [1, 0.3])}
          >
            <g opacity={crossIn}>
              <line x1={BOWL.x - 5} x2={BOWL.x + 5} y1={BOWL.y} y2={BOWL.y} />
              <line y1={BOWL.y - 5} y2={BOWL.y + 5} x1={BOWL.x} x2={BOWL.x} />
              <circle cx={BOWL.x} cy={BOWL.y} r={1.4} />
            </g>
            {radius > 0 && (
              <line
                x1={BOWL.x}
                y1={BOWL.y}
                x2={BOWL.x + Math.cos(-Math.PI / 4) * BOWL.ro * radius}
                y2={BOWL.y + Math.sin(-Math.PI / 4) * BOWL.ro * radius}
              />
            )}
            {outer > 0 && (
              <path
                d={arc(BOWL.x, BOWL.y, BOWL.ro, 180, 360 * outer)}
                strokeDasharray={dash}
              />
            )}
            {inner > 0 && (
              <path
                d={arc(BOWL.x, BOWL.y, BOWL.ri, 180, 360 * inner)}
                strokeDasharray={dash}
              />
            )}
            {/* 90° quadrant marker */}
            <path
              d={arc(BOWL.x, BOWL.y, 9, 270, 90 * p(46, 60))}
              opacity={0.8}
            />

            {/* leg: its axis, extended, and the angle off the baseline */}
            {leg > 0 && (
              <line
                x1={LEG.x0 - legUx * 26}
                y1={LEG.y0 - legUy * 26}
                x2={LEG.x0 - legUx * 26 + legUx * (legLen + 46) * leg}
                y2={LEG.y0 - legUy * 26 + legUy * (legLen + 46) * leg}
                strokeDasharray={dash}
              />
            )}
            {legArc > 0 && (
              <path
                d={arc(LEG.x1, LEG.y1, 16, 180, LEG_DEG * legArc)}
                transform={`translate(0 0)`}
              />
            )}

            {/* bezier handles of the swash and the stem join */}
            {HANDLES.map((hd, i) =>
              handles[i] > 0 ? (
                <g key={`hd${i}`} opacity={handles[i]}>
                  <line
                    x1={hd.a[0]}
                    y1={hd.a[1]}
                    x2={hd.a[0] + (hd.h[0] - hd.a[0]) * handles[i]}
                    y2={hd.a[1] + (hd.h[1] - hd.a[1]) * handles[i]}
                  />
                  <circle
                    cx={hd.a[0] + (hd.h[0] - hd.a[0]) * handles[i]}
                    cy={hd.a[1] + (hd.h[1] - hd.a[1]) * handles[i]}
                    r={px(3 * u)}
                    fill={knock}
                  />
                  <rect
                    x={hd.a[0] - px(3.5 * u)}
                    y={hd.a[1] - px(3.5 * u)}
                    width={px(7 * u)}
                    height={px(7 * u)}
                    fill={knock}
                  />
                </g>
              ) : null,
            )}

            {/* module ruler: seven strokes tall */}
            <g opacity={dims}>
              <line x1={-14} x2={-14} y1={0} y2={H * ruler} />
              {Array.from({ length: 8 }, (_, i) =>
                i * M <= H * ruler + 0.01 ? (
                  <g key={`m${i}`}>
                    {tick(-14, i * M, false, i % 7 === 0 ? 4 : 2.4)}
                  </g>
                ) : null,
              )}
              {/* width */}
              <line x1={0} x2={R_W * ruler} y1={-14} y2={-14} />
              {tick(0, -14, true, 4)}
              {ruler >= 1 && tick(R_W, -14, true, 4)}
              {/* bar thickness */}
              <line x1={56} x2={56} y1={0} y2={BAR_IN} />
              {tick(56, 0, false, 2.4)}
              {tick(56, BAR_IN, false, 2.4)}
            </g>
          </g>

          {/* measurement labels */}
          <g opacity={dims}>
            <Label x={R_W / 2} y={-14 - px(8 * u)} anchor="middle">
              124
            </Label>
            <Label x={-14 - px(10 * u)} y={H / 2} anchor="middle" rotate={-90}>
              7m · 134
            </Label>
            <Label x={56 + px(8 * u)} y={BAR_IN / 2 + px(4 * u)}>
              m 19.2
            </Label>
          </g>
          <Label
            x={BOWL.x + Math.cos(-Math.PI / 4) * BOWL.ro + px(6 * u)}
            y={BOWL.y + Math.sin(-Math.PI / 4) * BOWL.ro - px(4 * u)}
            o={radius}
          >
            R42
          </Label>
          <Label
            x={BOWL.x - BOWL.ri - px(8 * u)}
            y={BOWL.y - px(8 * u)}
            anchor="end"
            o={inner}
          >
            R23
          </Label>
          <Label x={BOWL.x + px(8 * u)} y={BOWL.y + px(18 * u)} o={crossIn}>
            80,43
          </Label>
          <Label x={LEG.x1 - 20} y={LEG.y1 - 6} anchor="end" o={legArc}>
            {`${LEG_DEG.toFixed(0)}°`}
          </Label>

          {/* the R: outline first, then the mesh fill sweeps round the bowl centre */}
          {!logo && (
            <g>
              {outline > 0 && (
                <path
                  d={REMOCN_R_PATH}
                  fill="none"
                  stroke={fg}
                  strokeWidth={px(1.4 * u)}
                  strokeLinejoin="round"
                  pathLength={1}
                  strokeDasharray={`${outline} 2`}
                  opacity={1 - markDone}
                />
              )}
              <g clipPath={`url(#fill${uid})`}>
                <path d={REMOCN_R_PATH} fill={pal.meshBase} />
                {blobs.map((_, i) => (
                  <path
                    key={i}
                    d={REMOCN_R_PATH}
                    fill={`url(#mesh${uid}${i})`}
                  />
                ))}
              </g>
            </g>
          )}

          {/* wordmark guides: its x-height, the shared baseline, a side bearing */}
          <g stroke={guide} strokeWidth={hair} fill="none">
            <line
              x1={WORD_X - span * xGrow}
              x2={WORD_X + span * xGrow}
              y1={WORD_XLINE}
              y2={WORD_XLINE}
              opacity={pal.guideAlpha * 0.85 * (1 - wordSettle * 0.7)}
            />
          </g>
          <g
            opacity={wordGuides * (1 - wordSettle * 0.75)}
            stroke={guide}
            strokeWidth={thin}
            fill="none"
          >
            <line
              x1={WORD_X - 3}
              x2={WORD_X - 3}
              y1={WORD_XLINE - 10}
              y2={H + 10}
              strokeDasharray={dash}
            />
          </g>
          <g
            opacity={p(156, 174, EASE_OUT) * (1 - wordSettle * 0.75)}
            stroke={guide}
            strokeWidth={thin}
          >
            <line x1={dimX} x2={dimX} y1={WORD_XLINE} y2={H} />
            {tick(dimX, WORD_XLINE, false, 4)}
            {tick(dimX, H, false, 4)}
          </g>
          <g
            opacity={p(156, 174, EASE_OUT) * (1 - wordSettle * 0.75)}
            fontFamily={mono}
            fontSize={fs}
            fontWeight={500}
            fill={guide}
            style={{ fontVariantNumeric: "tabular-nums" }}
          >
            <text x={dimX + px(8 * u)} y={(WORD_XLINE + H) / 2 + px(4 * u)}>
              0.54em
            </text>
            <text x={WORD_X} y={WORD_XLINE - px(7 * u)}>
              x-height
            </text>
            <text x={WORD_X} y={H + px(17 * u)}>
              baseline
            </text>
          </g>
          <g clipPath={`url(#word${uid})`}>
            <text
              x={WORD_X}
              y={H}
              fontFamily={fontFamily}
              fontWeight={600}
              fontSize={FONT}
              letterSpacing={FONT * TRACK}
              fill={fg}
            >
              {letters.map((ch, i) => {
                const k = letterP(i);
                const prev = i === 0 ? 0 : (1 - letterP(i - 1)) * RISE;
                return (
                  <tspan
                    key={i}
                    dy={(1 - k) * RISE - prev}
                    fillOpacity={0.15 + k * 0.85}
                  >
                    {ch}
                  </tspan>
                );
              })}
            </text>
          </g>
        </g>
      </svg>

      {logo && (
        <div
          style={{
            position: "absolute",
            left: markScreen.left,
            top: markScreen.top,
            height: markScreen.size,
            display: "flex",
            alignItems: "center",
            opacity: logoIn,
            filter: `blur(${(1 - logoIn) * 6 * u}px)`,
            transform: `scale(${0.96 + logoIn * 0.04})`,
            transformOrigin: "left center",
          }}
        >
          {logo}
        </div>
      )}

      {!transparent ? (
        <AbsoluteFill
          style={{
            background: `radial-gradient(ellipse 75% 70% at 50% 48%, transparent 55%, ${pal.vignette} 100%)`,
          }}
        />
      ) : null}
      {!transparent && grain ? <Grain opacity={pal.grain} /> : null}
    </AbsoluteFill>
  );
}
